<?php use App\Models\Company; use Illuminate\Support\Facades\Gate; use Livewire\Attributes\Title; use Livewire\Component; new #[Title('Companies')] class extends Component { public array $companies=[];public function mount():void{$this->companies=Company::orderBy('name')->get()->keyBy('id')->map(fn($c)=>$c->only(['name','code','address','email','phone','document_prefix','is_active']))->all();}public function save():void{Gate::authorize('admin.company.update');$this->validate(['companies.*.name'=>['required','max:255'],'companies.*.code'=>['required','max:20'],'companies.*.address'=>['nullable','max:2000'],'companies.*.email'=>['nullable','email'],'companies.*.phone'=>['nullable','max:100'],'companies.*.document_prefix'=>['required','max:20'],'companies.*.is_active'=>['boolean']]);foreach($this->companies as $id=>$data)Company::findOrFail($id)->update($data);Flux::toast(text:'Company settings saved',variant:'success');}}; ?>
<section class="w-full p-6"><flux:heading size="xl">Companies and document branding</flux:heading><form wire:submit="save" class="mt-6 max-w-4xl space-y-6">@foreach($companies as $id=>$company)<flux:card wire:key="company-{{$id}}" class="grid gap-4 md:grid-cols-2"><flux:input wire:model="companies.{{$id}}.name" label="Company name"/><flux:input wire:model="companies.{{$id}}.code" label="Code"/><flux:textarea class="md:col-span-2" wire:model="companies.{{$id}}.address" label="Address"/><flux:input wire:model="companies.{{$id}}.email" label="Email"/><flux:input wire:model="companies.{{$id}}.phone" label="Phone"/><flux:input wire:model="companies.{{$id}}.document_prefix" label="Document prefix"/><flux:switch wire:model="companies.{{$id}}.is_active" label="Active"/></flux:card>@endforeach<div class="flex justify-end"><flux:button type="submit" variant="primary">Save company settings</flux:button></div></form></section>
